import py4godot.classes.Tweener as py4godot_tweener 
from py4godot.wrappers.wrappers import CPPAwaitTweenerWrapper


class AwaitTweener(py4godot_tweener.Tweener):
  r'''
		`AwaitTweener` is used to await a specified signal, allowing asynchronous steps in `Tween` animation. See `Tween.tween_await` for more usage information.
		The `signal Tweener.finished` signal is emitted when either the awaited signal is received, when timeout is reached, or when the target object is freed.
	'''

  @staticmethod
  def constructor():
    class_ = AwaitTweener.construct_without_init()
    class_._ptr = constructor(174,0, ())
    return class_
  @staticmethod
  def new():
    class_ = AwaitTweener.construct_without_init()
    class_._ptr = constructor(174,0, ())
    return class_
  def __init__(self):
    self._ptr =  CPPAwaitTweenerWrapper()
    self.casted_from = None
    if c_utils.shouldCreateObject:
      self._ptr = constructor(174,0, ())


  def generate_wrapper(self):
    return CPPAwaitTweenerWrapper()
  def init_signals(self):
    super().init_signals()

  @staticmethod
  def construct_without_init():
    cls = AwaitTweener.__new__(AwaitTweener)
    cls.shouldBeDeleted = True
    cls.casted_from = None
    cls.constructed_from_python = False
    cls.init_signals()
    return cls
  @staticmethod
  def get_type():
    return 'AwaitTweener'

  def __del__(self):
    if self.casted_from is None:
      self._ptr.call_with_return(54, ())
      self._ptr = None
  @staticmethod
  def cast(other:'Object'):
    assert other != None # Object to be casted must not be None
    cls = AwaitTweener.construct_without_init()
    cls._ptr = CPPAwaitTweenerWrapper()
    cls._ptr_before = other._ptr # Save pointer
    cls._ptr.copy_gdowner(cls._ptr_before)
    cls.casted_from = other
    return cls
  @staticmethod
  def cast_without_reference(other: 'Object'):
    assert other != None # Object to be casted must not be None
    cls = AwaitTweener.construct_without_init()
    cls._ptr = CPPAwaitTweenerWrapper()
    cls._ptr_before = other._ptr # Save pointer
    cls._ptr.copy_gdowner(cls._ptr_before)
    return cls

  @functools.native_method
  def set_timeout(self, timeout:'float'   ) -> 'typing.Self':
    r'''
				Sets the maximum time an `AwaitTweener` can wait for the signal. Can be used as a safeguard for signals that may never be emitted. If not specified, the tweener will wait indefinitely.
			'''

    assert isinstance(timeout, (int, float)), 'timeout must be int or float'







    _ret = AwaitTweener.construct_without_init()
    _ret._ptr = self._ptr.call_with_return(53,tuple([timeout]))
    return smart_cast(_ret) if not _ret._ptr.is_null() else None



register_cast_function('AwaitTweener', AwaitTweener.cast)
register_class('AwaitTweener', AwaitTweener)
